using ModelContextProtocol.Server;
using System.ComponentModel;

[McpServerToolType]
public static class ConfigTools
{
    [McpServerTool, Description("Look up a configuration value by key name.")]
    public static string GetConfigValue(
        [Description("The configuration key to look up (e.g. 'MaxRetries', 'Timeout')")] string key)
    {
        var config = AppConfiguration.Current;
        return config.TryGetValue(key, out var value)
            ? $"{key} = {value}"
            : $"Key '{key}' not found. Available keys: {string.Join(", ", config.Keys)}";
    }

    [McpServerTool, Description("List all available configuration keys.")]
    public static string ListConfigKeys()
    {
        return string.Join("\n", AppConfiguration.Current.Keys.Order());
    }
}

using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Text.Json;

[McpServerResourceType]
public static class ConfigResources
{
    [McpServerResource(
        UriTemplate = "config://app/settings",
        Name = "App Settings",
        MimeType = "application/json"),
     Description("Returns the full application configuration as JSON.")]
    public static string GetAllSettings()
    {
        return JsonSerializer.Serialize(AppConfiguration.Current,
            new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerResource(
        UriTemplate = "config://app/settings/{section}",
        Name = "Config Section",
        MimeType = "application/json"),
     Description("Returns configuration values for a specific section (e.g. 'database', 'logging').")]
    public static string GetSection(string section)
    {
        var sectionPrefix = section.ToLowerInvariant() + ":";
        var filtered = AppConfiguration.Current
            .Where(kv => kv.Key.StartsWith(sectionPrefix, StringComparison.OrdinalIgnoreCase))
            .ToDictionary(kv => kv.Key, kv => kv.Value);

        return filtered.Count > 0
            ? JsonSerializer.Serialize(filtered, new JsonSerializerOptions { WriteIndented = true })
            : JsonSerializer.Serialize(new { error = $"No settings found for section '{section}'" });
    }
}

/// <summary>
/// Sample in-memory configuration store. Replace with a real config source in production.
/// </summary>
public static class AppConfiguration
{
    public static Dictionary<string, string> Current { get; } = new(StringComparer.OrdinalIgnoreCase)
    {
        ["Database:ConnectionString"] = "Server=localhost;Database=AppDb;Trusted_Connection=true",
        ["Database:MaxPoolSize"] = "100",
        ["Database:Timeout"] = "30",
        ["Logging:Level"] = "Information",
        ["Logging:Format"] = "json",
        ["App:MaxRetries"] = "3",
        ["App:Timeout"] = "60",
        ["App:Environment"] = "Development",
    };
}

